function getKillerPuzzleByDifficulty(difficulty) {
  const day = Math.floor((new Date() - new Date('2025-01-01')) / 86400000);
  const pool = KILLER_PUZZLES.filter(p => p.difficulty === difficulty);
  return pool[day % pool.length];
}
